-- Hosbah queries.

-- name: ListLogDrainsOfTeam :many
-- Team scope: every log drain of a team, newest first.
SELECT * FROM log_drains WHERE team_id = sqlc.arg('team_id') ORDER BY created_at DESC, id;

-- name: ListLogDrainsOfApp :many
-- Team scope: a team's log drains that apply to a given app — scoped to that app plus the team's
-- app_id = '' (every app) drains.
SELECT * FROM log_drains
WHERE team_id = sqlc.arg('team_id') AND (app_id = sqlc.arg('app_id') OR app_id = '')
ORDER BY created_at DESC, id;

-- name: LogDrainInTeam :one
-- Team scope: one log drain of a team, by id.
SELECT * FROM log_drains WHERE id = sqlc.arg('id') AND team_id = sqlc.arg('team_id');

-- name: InsertLogDrain :one
INSERT INTO log_drains (team_id, app_id, name, kind, config_json, auth_sealed, internal, enabled, created_by)
VALUES (sqlc.arg('team_id'), sqlc.arg('app_id'), sqlc.arg('name'), sqlc.arg('kind'), sqlc.arg('config_json'),
    sqlc.arg('auth_sealed'), sqlc.arg('internal'), sqlc.arg('enabled'), sqlc.arg('created_by'))
RETURNING *;

-- name: UpdateLogDrainInTeam :one
-- Team scope: a drain's editable settings (its kind never changes).
UPDATE log_drains SET name = sqlc.arg('name'), app_id = sqlc.arg('app_id'), config_json = sqlc.arg('config_json'),
    auth_sealed = sqlc.arg('auth_sealed'), internal = sqlc.arg('internal'), enabled = sqlc.arg('enabled'),
    updated_at = now()
WHERE id = sqlc.arg('id') AND team_id = sqlc.arg('team_id')
RETURNING *;

-- name: DeleteLogDrainInTeam :execrows
DELETE FROM log_drains WHERE id = sqlc.arg('id') AND team_id = sqlc.arg('team_id');

-- name: RecordLogDrainSuccess :exec
-- The agent's periodic status report: a successful ship adds to the running totals.
UPDATE log_drains SET shipped = shipped + sqlc.arg('shipped')::bigint, dropped = dropped + sqlc.arg('dropped')::bigint,
    last_success_at = sqlc.arg('at')::timestamptz, updated_at = now()
WHERE id = sqlc.arg('id') AND team_id = sqlc.arg('team_id');

-- name: RecordLogDrainError :exec
UPDATE log_drains SET dropped = dropped + sqlc.arg('dropped')::bigint, last_error_at = sqlc.arg('at')::timestamptz,
    last_error = sqlc.arg('last_error'), updated_at = now()
WHERE id = sqlc.arg('id') AND team_id = sqlc.arg('team_id');
